SELECT A.FUND_BALAN_CLS, A.FUND_BALAN_CLS_NM, A.FUND_BALAN_ITM_CD, A.FUND_BALAN_ITM_CD_NM, A.ARRAY_ORD, B.CONEND_SCD_GCT, C.FUND_BALAN_AMT, CASE WHEN A.FUND_BALAN_CLS = 'A1' AND A.FUND_BALAN_ITM_CD = 'D1012' THEN NVL(B.CONEND_SCD_GCT, 0) - NVL(C.FUND_BALAN_AMT, 0) END GAP, D.CTOT_AMT FROM (SELECT B.COMM_CD AS FUND_BALAN_CLS, B.COMM_CD_NM AS FUND_BALAN_CLS_NM, A.COMM_CD AS FUND_BALAN_ITM_CD, A.COMM_CD_NM AS FUND_BALAN_ITM_CD_NM, A.ARRAY_ORD FROM CO_COMM_CD A JOIN CO_COMM_CD B ON B.COMM_GRP_CD = 'PM843' AND B.SYS_CD = 'icms' AND A.SYS_CD = B.SYS_CD AND A.REF_CD_1 = B.COMM_CD WHERE A.COMM_GRP_CD = 'PM844' AND A.SYS_CD = 'icms' AND A.USE_YN = 'Y' AND A.REF_CD_3 IN ('Y', 'N')) A LEFT JOIN (SELECT CASE WHEN NVL(A.DRCT_INPUT_YN, 'N') = 'N' AND NVL(B.SITE_VAT_CLS, '1') <> '2' THEN ROUND(A.CONEND_SCD_GCT * (1 + 0.1 * (1 - NVL(A.REMIT_RATE, 0)/100)), 0) ELSE A.CONEND_SCD_GCT END CONEND_SCD_GCT FROM PMF_FUND_BALAN_MST A JOIN CO_ORG B ON A.SITE_CD = B.ORG_CD WHERE A.SITE_CD = 'test' AND A.YM = '202501') B ON A.FUND_BALAN_CLS = 'A1' AND A.FUND_BALAN_ITM_CD = 'D1012' ORDER BY A.ARRAY_ORD
